-- Additive: distinguish person-created (Manual) alerts from system-generated ones.
-- ADD COLUMN IF NOT EXISTS is a no-op when the column already exists as nullable;
-- backfill NULL rows then enforce NOT NULL so Prisma P2032 cannot recur.
ALTER TABLE "MonitoringAlert" ADD COLUMN IF NOT EXISTS "autoGenerated" BOOLEAN;
ALTER TABLE "MonitoringAlert" ADD COLUMN IF NOT EXISTS "alertSource" TEXT;
UPDATE "MonitoringAlert" SET "autoGenerated" = true WHERE "autoGenerated" IS NULL;
UPDATE "MonitoringAlert" SET "alertSource" = 'System' WHERE "alertSource" IS NULL;
ALTER TABLE "MonitoringAlert" ALTER COLUMN "autoGenerated" SET DEFAULT true;
ALTER TABLE "MonitoringAlert" ALTER COLUMN "alertSource" SET DEFAULT 'System';
ALTER TABLE "MonitoringAlert" ALTER COLUMN "autoGenerated" SET NOT NULL;
ALTER TABLE "MonitoringAlert" ALTER COLUMN "alertSource" SET NOT NULL;
